<script setup lang="ts">
import type {Row} from '~/utils/resources'
const days=ref(30),busy=ref(''),api=useApi(),toast=useToast()
const {data,error,refresh}=await useFetch<{items:Row[];now:string}>('/api/renewals',{query:{days}})
const groups=computed(()=>{const at=Date.parse(data.value?.now||new Date().toISOString());const rows=data.value?.items||[];return [{label:'Expired · needs a decision',color:'error' as const,items:rows.filter(s=>Date.parse(s.expiryDate)<at)},{label:'Due in the next 7 days',color:'warning' as const,items:rows.filter(s=>Date.parse(s.expiryDate)>=at&&Date.parse(s.expiryDate)<=at+7*86400000)},{label:'Coming up',color:'primary' as const,items:rows.filter(s=>Date.parse(s.expiryDate)>at+7*86400000)}]})
async function renew(s:Row){busy.value=s.id;try{await api(`/subscriptions/${s.id}/renew`,{method:'POST'});await refresh();toast.add({title:'Renewal complete',description:`${s.number} has been extended.`,color:'success'})}catch(e){toast.add({title:errorMessage(e),color:'error'})}finally{busy.value=''}}
</script>
<template><div class="page space-y-6"><div class="page-head"><div><h1>Renewal radar</h1><p>Make a decision before a customer’s contract slips through the cracks.</p></div><USelect v-model="days" :items="[{label:'Next 7 days',value:7},{label:'Next 30 days',value:30},{label:'Next 90 days',value:90}]" aria-label="Renewal window"/></div><UAlert v-if="error" color="error" :title="errorMessage(error)"><template #actions><UButton @click="refresh()">Retry</UButton></template></UAlert><div class="grid lg:grid-cols-3 gap-5"><UCard v-for="group in groups" :key="group.label"><template #header><div class="flex justify-between items-center"><h2 class="font-medium text-sm">{{group.label}}</h2><UBadge :color="group.color" variant="subtle">{{group.items.length}}</UBadge></div></template><div class="space-y-4"><div v-for="s in group.items" :key="s.id" class="rounded-lg border border-default p-4"><div class="flex justify-between gap-2"><NuxtLink :to="`/subscriptions/${s.id}`" class="font-semibold text-sm hover:text-primary">{{s.customer.name}}</NuxtLink><UBadge v-if="s.autoRenew" size="xs" color="neutral" variant="subtle">Auto renew</UBadge></div><p class="text-xs text-muted mt-1">{{s.number}}</p><p class="text-sm mt-4">{{s.plan.name}}</p><div class="flex justify-between text-xs text-muted mt-2"><span>Ends {{date(s.expiryDate)}}</span><span>{{money(s.mrr)}} MRR</span></div><div class="flex gap-2 mt-4"><UButton v-if="s.plan.renewable&&!s.autoRenew" size="xs" :loading="busy===s.id" @click="renew(s)">Renew contract</UButton><UButton :to="`/subscriptions/${s.id}`" size="xs" color="neutral" variant="outline">Review</UButton></div><p v-if="s.plan.autoClose" class="text-xs text-muted mt-3">Closes automatically at expiry.</p></div><p v-if="!group.items.length" class="text-sm text-muted py-8 text-center">Nothing in this queue.</p></div></UCard></div></div></template>
